mapper.select:
SELECT s.bill_stg_id AS stage_id,s.prj_id AS project_id,s.bill_stg_nm AS name,
  s.sply_amt AS supply,s.bill_plan_dt AS date
FROM prj.bill_stg s WHERE s.prj_id=#{projectId} AND s.bill_stg_id=#{stageId}

SELECT o.num_val FROM cmn.oprt_std o
WHERE o.oprt_std_id='VAT_RATE' AND o.aply_bgn_ym <= #{month}
ORDER BY o.aply_bgn_ym DESC LIMIT 1

mapper.sql:
WHERE extract(year from x.effective_date)=#{year}
AND x.bill_stts_cd=#{status}
AND x.contract_type=#{type}
AND x.customer_id=#{customerId}
AND (x.project_name ILIKE '%' || #{q} || '%'
  OR x.bill_no ILIKE '%' || #{q} || '%' OR x.customer_name ILIKE '%' || #{q} || '%')
